{
  "@context": "https://schema.org",
  "@type": "HowTo",
  "name": "Como converter imagens com CovertConvert",
  "description": "Converta HEIC, WebP, AVIF e outros formatos de imagem para JPG ou PNG inteiramente no seu navegador.",
  "step": [
    {
      "@type": "HowToStep",
      "name": "Selecionar arquivos",
      "text": "Arraste arquivos de imagem para o conversor ou clique para navegar. Suporta HEIC, WebP, AVIF, TIFF, PNG, BMP e GIF."
    },
    {
      "@type": "HowToStep",
      "name": "Escolher formato de saída",
      "text": "Selecione JPEG para arquivos menores ou PNG para qualidade sem perdas. Ajuste a qualidade JPEG se desejar."
    },
    {
      "@type": "HowToStep",
      "name": "Conversão acontece localmente",
      "text": "Seu navegador processa as imagens usando WebAssembly. Arquivos nunca saem do seu dispositivo."
    },
    {
      "@type": "HowToStep",
      "name": "Baixar resultados",
      "text": "Arquivos convertidos são baixados automaticamente. Múltiplos arquivos são agrupados em um arquivo ZIP."
    }
  ]
}

